export default function UserStats({ users }: UserStatsProps) {
  // Derived values calculated directly during render
  const activeCount = users.filter((user) => user.isActive).length
  const inactiveCount = users.length - activeCount
  const activePercentage =
    users.length > 0 ? Math.round((activeCount / users.length) * 100) : 0

  return (
    <div>
      <h2>User Statistics</h2>
      <p>Active Users: {activeCount}</p>
      <p>Inactive Users: {inactiveCount}</p>
      <p>Active Percentage: {activePercentage}%</p>
    </div>
  )
}

